module freq_divbyfrac #(
    parameter MUL2_DIV_CLK = 7
) (
    input               rst_n,
    input               clk,
    output              clk_div
);

reg [31:0] count;
reg div_clk;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) count <= 0; else count <= count + 1;
end

always @(count) begin
    case (count)
        0, 1, 2, 3, 4, 5, 6: div_clk <= 1'b0;
        default: div_clk <= 1'b1;
    endcase
end

assign clk_div = div_clk;

endmodule
